// Label placement is schematic. Shared stations use one physical node and one label.
export function labelPlacement(name){const [x,y]=positions[name];const primary=lines.find(l=>l.names.includes(name));const i=primary.names.indexOf(name);if(name==='一大会址·黄陂南路')return {x:x-18,y:y+5,anchor:'end'};if(name==='人民广场')return {x:x+22,y:y+31,anchor:'start'};if(name==='老西门'||name==='陕西南路')return {x:x+18,y:y+29,anchor:'start'};if(name==='南京东路')return {x:x+18,y:y+28,anchor:'start'};if(name==='四平路')return {x:x+20,y:y+28,anchor:'start'};if(primary.id==='1'&&i>=13&&i<=20)return {x:x-20,y:y+5,anchor:'end'};if(primary.id==='8'&&i>=16&&i<=18)return {x:x-20,y:y+5,anchor:'end'};if(primary.id==='10'&&[14,16,18,19].includes(i))return {x:x+20,y:y+5,anchor:'start'};return {x:x+7,y:y-22,anchor:'start',rotate:-45};}
